def shortest_path(graph, source, target):
    if target not in graph:
        return (float('inf'), None)
    priority_queue = [(0, source)]
    shortest_paths = {source: (0, [source])}
    while priority_queue:
        current_cost, current_node = priority_queue.pop(0)
        if current_node == target:
            return (current_cost, shortest_paths[current_node][1])
        for neighbor, weight in graph.get(current_node, []):
            new_cost = current_cost + weight
            if neighbor not in shortest_paths or new_cost < shortest_paths[neighbor][0]:
                shortest_paths[neighbor] = (new_cost, shortest_paths[current_node][1] + [neighbor])
                priority_queue.append((new_cost, neighbor))
    return (float('inf'), None)
