def shortest_path(graph, source, target):
    import collections

    def dfs(vert, target, path):
        nonlocal targetPath
        path.append(vert)
        if vert == target:
            targetPath = path[:]
            return
        for nextVert, weight in graph[vert]:
            if not visited[nextVert]:
                visited[nextVert] = True
                dfs(nextVert, target, path)
                path.pop()
        visited[vert] = False
    if source not in graph or target not in graph:
        return (float('inf'), None)
    visited = {node: False for node in graph}
    targetPath = None
    visited[source] = True
    dfs(source, target, [])
    if not targetPath:
        return (float('inf'), None)
    distance = 0
    for i in range(len(targetPath) - 1):
        distance += graph[targetPath[i]][targetPath[i + 1]][1]
    return (distance, targetPath)
