def shortest_path(graph, source, target):
    distance = {}
    previous = {}
    for vertex in graph:
        distance = {'INF'}
        distance[0] = distance[vertex] = float('inf')
        distance[source] = 0
        previous[vertex] = None
    while distance[target] != float('inf'):
        for neighbor, weight in graph.get(target, []):
            if distance[neighbor] > distance[target] + weight:
                distance[neighbor] = distance[target] + weight
                previous[neighbor] = target
        del distance[target]
        target = min(distance, key=distance.get)
    path = []
    if previous[target] is not None:
        current = target
        while current is not None:
            path.append(current)
            current = previous[current]
        path.reverse()
    else:
        path = None
    return (distance[target], path)
